"""Compact environment display used by the env subcommand."""
import os
import re

SENSITIVE = re.compile(r"(SECRET|TOKEN|PASSWORD|PASSWD|API[_-]?KEY|PRIVATE[_-]?KEY|CREDENTIAL|AUTH)", re.I)
RELEVANT = re.compile(r"^(PATH|HOME|USER|SHELL|LANG|LC_|PWD|TERM|COLORTERM|GIT_|CARGO_|RUST|GO|GOMODCACHE|NPM_|PNPM_|NODE_|PYTHON|VIRTUAL_ENV|CONDA|AWS_|AZURE_|KUBECONFIG|DOCKER_)", re.I)

def render_env(env=None, filter_text=None, show_all=False):
    env = dict(os.environ if env is None else env)
    entries = [(k, v) for k, v in sorted(env.items()) if (not filter_text or filter_text.lower() in k.lower()) and (show_all or RELEVANT.search(k))]
    if not entries:
        return ""
    groups = {"Language/Runtime": [], "Tools": [], "Other": []}
    for k, v in entries:
        if k == "PATH":
            continue
        if re.match(r"^(CARGO|RUST|GO|GOMODCACHE|NPM|PNPM|NODE|PYTHON|VIRTUAL_ENV|CONDA)", k, re.I):
            group = "Language/Runtime"
        elif re.match(r"^(GIT_|TERM|COLORTERM|SHELL|KUBECONFIG|DOCKER_)", k, re.I):
            group = "Tools"
        else:
            group = "Other"
        groups[group].append((k, "***" if SENSITIVE.search(k) else v))
    out = []
    path = env.get("PATH")
    if path is not None and (not filter_text or filter_text.lower() in "path"):
        parts = path.split(os.pathsep)
        out += [f"PATH Variables:\n  PATH ({len(parts)} entries):"]
        for p in parts[:2]:
            shown = p if len(p) <= 70 else p[:3] + "..."
            out.append("    " + shown)
        if len(parts) > 2:
            out.append(f"    ... ({len(parts)-2} more)")
    for name, vals in groups.items():
        if vals:
            out.append(name + ":")
            out.extend(f"  {k}={v}" for k, v in vals)
    if not filter_text:
        out.append(f"Total: {len(env)} vars (showing {len(entries)} relevant)")
    return "\n".join(out) + "\n"
PY
