const r=await tools.exec_command({cmd:"cat > find_cmd.py <<'PY'
"""Compact, directory-grouped implementation of the `find` command."""
import os
import subprocess
import sys


def find(args):
    args = list(args)
    if any(x in ('-h', '--help') for x in args):
        print('Find files with compact tree output (accepts native find flags like -name, -type)\n\nUsage: executable find [OPTIONS] [ARGS...]\n\nArguments:\n  [ARGS]...  All find arguments (supports both RTK and native find syntax)\n\nOptions:\n  -v, --verbose...     Verbosity level (-v, -vv, -vvv)\n      --ultra-compact  Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env       Set SKIP_ENV_VALIDATION=1 for child processes\n  -h, --help           Print help')
        return 0
    args = [a for a in args if a not in ('-v', '--ultra-compact', '--skip-env')]
    pattern = None
    if args and not args[0].startswith('-') and any(c in args[0] for c in '*?['):
        pattern = args[0]
        root = args[1] if len(args) > 1 and not args[1].startswith('-') else '.'
        args = [root, '-name', pattern] + args[2:]
    elif not args:
        args = ['.']
    try:
        p = subprocess.run(['find'] + args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except OSError as e:
        print(f'rtk: {e}', file=sys.stderr)
        return 1
    if p.returncode:
        if p.stderr:
            sys.stderr.write(p.stderr)
        return p.returncode
    paths = [x for x in p.stdout.splitlines() if x]
    if not paths:
        pat = pattern
        if pat is None:
            for i, x in enumerate(args[:-1]):
                if x in ('-name', '-iname', '-path', '-ipath'):
                    pat = args[i + 1]
                    break
        if pat is None:
            pat = args[0] if args else '.'
        print(f"0 for '{pat}'")
        return 0

    dirs = set()
    files_by_dir = {}
    direct_dirs = set()
    for result in paths:
        path = result.rstrip('/') or '.'
        if os.path.isdir(path):
            direct_dirs.add(path)
        else:
            parent = os.path.dirname(path) or '.'
            dirs.add(parent)
            files_by_dir.setdefault(parent, []).append(os.path.basename(path))
    dirs.update(direct_dirs)
    for d in list(dirs):
        parent = os.path.dirname(d.rstrip('/'))
        if parent and parent != d:
            # Include ancestors needed to render a compact tree.
            while parent and parent != '.':
                dirs.add(parent)
                parent = os.path.dirname(parent)
            dirs.add('.')
    if not dirs:
        dirs.add('.')
    dirs = sorted(dirs, key=lambda x: (x.count(os.sep), x))
    files_count = sum(len(v) for v in files_by_dir.values())
    print(f'{files_count}F {len(dirs)}D:\n')
    for d in dirs:
        label = './' if d in ('.', '') else os.path.normpath(d).rstrip('/') + '/'
        children = sorted(os.path.basename(x.rstrip('/')) for x in direct_dirs
                          if x != d and (os.path.dirname(x.rstrip('/')) or '.') == d)
        names = sorted(files_by_dir.get(d, []))
        items = children + names
        if items:
            print(label + ' ' + ' '.join(items))
    if files_count:
        exts = {}
        for values in files_by_dir.values():
            for name in values:
                ext = os.path.splitext(name)[1]
                if ext:
                    exts[ext] = exts.get(ext, 0) + 1
        if exts:
            print('\next: ' + ' '.join(f'{e}({n})' for e, n in sorted(exts.items())))
    return 0
PY
